const finite=(v,fallback,min,max)=>Number.isFinite(v)?Math.max(min,Math.min(max,v)):fallback;
export function createTDGraph(projects,saved={}){const nodes=projects.map((p,i)=>{const old=(Array.isArray(saved?.nodes)?saved.nodes:[]).find(n=>n?.id===p.id)||{};return {id:p.id,x:finite(old.x,40+i%4*250,-3000,6000),y:finite(old.y,45+Math.floor(i/4)*170,-3000,6000),label:typeof old.label==='string'?old.label.slice(0,80):p.title,note:typeof old.note==='string'?old.note.slice(0,1500):'',image:Math.round(finite(old.image,0,0,Math.max(0,p.images.length-1))),brightness:finite(old.brightness,100,40,160),saturation:finite(old.saturation,100,0,160)}});const defaults=nodes.flatMap((node,i)=>{const links=[];if(i%4<3&&nodes[i+1])links.push([node.id,nodes[i+1].id]);if(i%4===0&&nodes[i+4])links.push([node.id,nodes[i+4].id]);return links});const ids=new Set(nodes.map(n=>n.id)),seen=new Set(),edges=[];for(const pair of [...(saved?.connectionsVersion===1?[]:defaults),...(Array.isArray(saved?.edges)?saved.edges:[])]){if(!Array.isArray(pair)||pair.length!==2||pair[0]===pair[1]||!ids.has(pair[0])||!ids.has(pair[1]))continue;const key=pair.join(':');if(!seen.has(key)){seen.add(key);edges.push(pair)}}return {nodes,edges,connectionsVersion:1};}
export function moveTDNode(node,dx,dy,scale){return {x:Math.max(-3000,Math.min(6000,node.x+dx/Math.max(.1,scale))),y:Math.max(-3000,Math.min(6000,node.y+dy/Math.max(.1,scale)))}}
export function tdWire(from,to){const x=from.x+148,y=from.y+46,tx=to.x,ty=to.y+46,c=Math.max(60,Math.abs(tx-x)*.45);return `M${x},${y} C${x+c},${y} ${tx-c},${ty} ${tx},${ty}`;}
